', direction=None, fact=None, file_name='/workspace/sandbox/variants/accessible_basic/shopping-home-page--framework-vanilla-js--style-modern/google/gemini-3-flash-preview__s3/style.css', full_command_text=None, has_write_file_redirection=None, hook_message=None, intention='Edit file', new_file_contents=':root {
    --primary-color: #1a1a1a;
    --secondary-color: #f4f4f4;
    --accent-color: #3d5a80;
    --text-color: #333;
    --text-light: #666;
    --bg-color: #ffffff;
    --white: #ffffff;
    --border-color: #e0e0e0;
    --transition: all 0.3s ease;
    --container-width: 1200px;
    --header-height: 70px;
}

* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    line-height: 1.6;
    color: var(--text-color);
    background-color: var(--bg-color);
    overflow-x: hidden;
}

ul {
    list-style: none;
}

a {
    text-decoration: none;
    color: inherit;
    transition: var(--transition);
}

img {
    max-width: 100%;
    height: auto;
    display: block;
}

.container {
    max-width: var(--container-width);
    margin: 0 auto;
    padding: 0 20px;
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

.skip-link {
    position: absolute;
    top: -40px;
    left: 0;
    background: var(--primary-color);
    color: white;
    padding: 8px;
    z-index: 100;
    transition: top 0.3s;
}

.skip-link:focus {
    top: 0;
}

/* Header & Navigation */
header {
    height: var(--header-height);
    border-bottom: 1px solid var(--border-color);
    position: sticky;
    top: 0;
    background: var(--white);
    z-index: 1000;
}

.header-container {
    display: flex;
    align-items: center;
    justify-content: space-between;
    height: 100%;
}

.logo {
    font-size: 1.5rem;
    font-weight: 700;
    letter-spacing: 1px;
}

.logo span {
    font-weight: 300;
}

.nav-links {
    display: flex;
    gap: 2rem;
}

.nav-links a {
    font-weight: 500;
    font-size: 0.9rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.nav-links a:hover {
    color: var(--accent-color);
}

.header-actions {
    display: flex;
    align-items: center;
    gap: 1.5rem;
}

.search-form {
    display: flex;
    align-items: center;
    background: var(--secondary-color);
    padding: 5px 10px;
    border-radius: 20px;
}

.search-form input {
    background: transparent;
    border: none;
    padding: 5px;
    outline: none;
    width: 150px;
    font-size: 0.9rem;
}

.search-form button {
    background: transparent;
    border: none;
    cursor: pointer;
    display: flex;
    align-items: center;
    color: var(--text-light);
}

.action-link {
    display: flex;
    align-items: center;
    position: relative;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -10px;
    background: var(--accent-color);
    color: white;
    font-size: 0.7rem;
    padding: 2px 6px;
    border-radius: 50%;
    font-weight: 700;
}

/* Mobile Nav Toggle */
.mobile-nav-toggle {
    display: none;
    background: transparent;
    border: none;
    cursor: pointer;
    padding: 10px;
    z-index: 1001;
}

.hamburger {
    display: block;
    width: 25px;
    height: 2px;
    background: var(--primary-color);
    position: relative;
    transition: background 0.3s;
}

.hamburger::before, .hamburger::after {
    content: '';
    position: absolute;
    width: 25px;
    height: 2px;
    background: var(--primary-color);
    transition: transform 0.3s;
}

.hamburger::before { top: -8px; }
.hamburger::after { bottom: -8px; }

.hamburger.open {
    background: transparent;
}

.hamburger.open::before {
    transform: translateY(8px) rotate(45deg);
}

.hamburger.open::after {
    transform: translateY(-8px) rotate(-45deg);
}

/* Hero Section */
.hero {
    background-color: var(--secondary-color);
    padding: 60px 0;
    overflow: hidden;
}

.hero-container {
    display: flex;
    align-items: center;
    gap: 40px;
}

.hero-content {
    flex: 1;
}

.hero-content h1 {
    font-size: 3.5rem;
    line-height: 1.1;
    margin-bottom: 20px;
    color: var(--primary-color);
}

.hero-content p {
    font-size: 1.2rem;
    color: var(--text-light);
    margin-bottom: 30px;
    max-width: 500px;
}

.hero-image {
    flex: 1;
}

.hero-image img {
    border-radius: 4px;
    box-shadow: 0 20px 40px rgba(0,0,0,0.1);
}

/* Buttons */
.btn {
    display: inline-block;
    padding: 12px 30px;
    border-radius: 4px;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 1px;
    cursor: pointer;
    border: 2px solid transparent;
    transition: var(--transition);
}

.btn-primary {
    background: var(--primary-color);
    color: white;
}

.btn-primary:hover {
    background: #333;
}

.btn-secondary {
    background: var(--accent-color);
    color: white;
}

.btn-outline {
    border-color: var(--primary-color);
    background: transparent;
}

.btn-outline:hover {
    background: var(--primary-color);
    color: white;
}

/* Featured Products */
.featured-products {
    padding: 80px 0;
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 40px;
}

.section-header h2 {
    font-size: 2rem;
}

.view-all {
    font-weight: 600;
    border-bottom: 2px solid var(--accent-color);
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: 30px;
}

.product-card {
    position: relative;
    transition: var(--transition);
}

.product-image {
    position: relative;
    overflow: hidden;
    background: var(--secondary-color);
    aspect-ratio: 3/4;
}

.product-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    transition: transform 0.5s ease;
}

.product-card:hover .product-image img {
    transform: scale(1.05);
}

.add-to-cart {
    position: absolute;
    bottom: -50px;
    left: 0;
    width: 100%;
    background: rgba(26, 26, 26, 0.9);
    color: white;
    border: none;
    padding: 12px;
    cursor: pointer;
    transition: bottom 0.3s ease;
}

.product-card:hover .add-to-cart {
    bottom: 0;
}

.product-info {
    padding: 15px 0;
}

.product-info h3 {
    font-size: 1rem;
    margin-bottom: 5px;
    font-weight: 500;
}

.product-info .price {
    font-weight: 700;
    color: var(--primary-color);
}

/* Deals Section */
.deals {
    padding-bottom: 80px;
}

.deals-banner {
    background: linear-gradient(rgba(0,0,0,0.4), rgba(0,0,0,0.4)), url('https://images.unsplash.com/photo-1441984904996-e0b6ba687e04?auto=format&fit=crop&w=1200&q=80');
    background-size: cover;
    background-position: center;
    padding: 80px 40px;
    color: white;
    text-align: center;
    border-radius: 4px;
}

.deals-content {
    max-width: 600px;
    margin: 0 auto;
}

.deals-content h2 {
    font-size: 2.5rem;
    margin-bottom: 15px;
}

.deal-timer {
    font-size: 1.5rem;
    font-weight: 700;
    margin: 20px 0 30px;
    font-variant-numeric: tabular-nums;
}

/* Editorial Section */
.editorial {
    padding-bottom: 80px;
}

.editorial-grid {
    display: grid;
    grid-template-columns: 2fr 1fr;
    gap: 30px;
}

.editorial-item {
    display: flex;
    flex-direction: column;
}

.editorial-image {
    aspect-ratio: 16/9;
    overflow: hidden;
    margin-bottom: 20px;
}

.editorial-item.large .editorial-image {
    aspect-ratio: 21/9;
}

.editorial-image img {
    width: 100%;
    height: 100%;
    object-fit: cover;
}

.editorial-text h2, .editorial-text h3 {
    margin-bottom: 10px;
}

.link-more {
    display: inline-block;
    margin-top: 10px;
    font-weight: 600;
    text-transform: uppercase;
    font-size: 0.8rem;
    letter-spacing: 1px;
    border-bottom: 2px solid var(--primary-color);
}

/* Footer */
footer {
    background: var(--primary-color);
    color: white;
    padding: 80px 0 20px;
}

.footer-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr 2fr;
    gap: 40px;
    margin-bottom: 60px;
}

.footer-brand .logo {
    margin-bottom: 20px;
}

.footer-links h3, .footer-newsletter h3 {
    font-size: 1.1rem;
    margin-bottom: 20px;
    text-transform: uppercase;
    letter-spacing: 1px;
}

.footer-links ul li {
    margin-bottom: 10px;
}

.footer-links a {
    color: #ccc;
}

.footer-links a:hover {
    color: white;
}

.footer-newsletter p {
    color: #ccc;
    margin-bottom: 20px;
}

.newsletter-form {
    display: flex;
    gap: 10px;
}

.newsletter-form input {
    flex: 1;
    padding: 10px;
    border: none;
    border-radius: 4px;
}

.footer-bottom {
    border-top: 1px solid #333;
    padding-top: 20px;
    text-align: center;
    color: #666;
    font-size: 0.9rem;
}

/* Responsive */
@media (max-width: 992px) {
    .hero-container {
        flex-direction: column;
        text-align: center;
    }
    .hero-content h1 {
        font-size: 2.5rem;
    }
    .hero-content p {
        margin: 0 auto 30px;
    }
    .footer-grid {
        grid-template-columns: 1fr 1fr;
    }
    .editorial-grid {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    header {
        height: auto;
        padding: 15px 0;
    }
    .nav-links {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        width: 100%;
        background: var(--white);
        flex-direction: column;
        padding: 20px;
        gap: 1.5rem;
        border-bottom: 1px solid var(--border-color);
        box-shadow: 0 10px 10px rgba(0,0,0,0.05);
    }
    .nav-links.active {
        display: flex;
    }
    .mobile-nav-toggle {
        display: block;
    }
    .header-actions .search-form {
        display: none;
    }
}
